size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1025); // 0..1024
if (s.size() > cap) s.resize(cap);
const unsigned char* in_ptr = (const unsigned char*)s.data();
size_t insize = s.size();

// Choose output container format.
unsigned int rf = *FUZZ_PARAM(unsigned int) % 3;
ZopfliFormat fmt = rf == 0 ? ZOPFLI_FORMAT_GZIP : (rf == 1 ? ZOPFLI_FORMAT_ZLIB : ZOPFLI_FORMAT_DEFLATE);

// The API appends into a caller-managed dynamic buffer; start from empty.
unsigned char* out = NULL;
size_t outsize = 0;

// First compression call.
ZopfliCompress(options, fmt, in_ptr, insize, &out, &outsize);

// Exercise append behavior with a second call: use a deterministic variant of input
// to avoid relying on additional randomness in a loop.
if ((insize > 0) && ((*FUZZ_PARAM(unsigned int)) & 1)) {
    size_t half = insize / 2;
    const unsigned char* in2 = in_ptr;
    size_t in2size = half;
    ZopfliCompress(options, fmt, in2, in2size, &out, &outsize);
}

