// Construct a new ZopfliOptions instance with valid initialization and sensible fuzzed tweaks.
// No inputs: we allocate caller-owned storage and return it.
ZopfliOptions* options = (ZopfliOptions*)malloc(sizeof(ZopfliOptions));
if (!options) { FUZZ_BAIL(); }

// Initialize with library defaults as required before use.
ZopfliInitOptions(options);

// Apply fuzzed but valid customizations within documented constraints.
