import random
import struct

# Generator for arbitrary binary data inputs tailored for Zopfli compressors.
# Produces valid, interesting byte sequences to exercise different patterns.

_MAX_TOTAL = 4096
_TARGET_MAX = 1024  # stubs cap inputs at 1024


def _rand(r, a, b):
    # Safe randint with clamping and swap if needed
    if b < a:
        a, b = b, a
    return r.randint(a, b)


def _choose(r, seq):
    return seq[r.randrange(len(seq))]


def _gen_repeating(r, length):
    b = _choose(r, [0x00, 0x20, 0x41, 0x7F, 0xFF])
    return bytes([b]) * length


def _gen_incrementing(r, length):
    start = _rand(r, 0, 255)
    return bytes((start + i) & 0xFF for i in range(length))


def _gen_random_low_entropy(r, length):
    alphabet_size = _rand(r, 2, 6)
    alphabet = bytes(sorted({_rand(r, 0, 255) for _ in range(alphabet_size)})) or b"\x00\x01"
    return bytes(alphabet[r.randrange(len(alphabet))] for _ in range(length))


def _gen_random_high_entropy(r, length):
    return bytes(r.getrandbits(8) for _ in range(length))


def _gen_text_english(r, length):
    words = [
        b"the", b"and", b"compression", b"zopfli", b"deflate", b"data", b"block",
        b"split", b"repeat", b"match", b"literal", b"entropy", b"test", b"fuzz"
    ]
    out = bytearray()
    while len(out) < length:
        w = _choose(r, words)
        out.extend(w)
        if r.random() < 0.5:
            out.extend(b" ")
    return bytes(out[:length])


def _gen_binary_patterns(r, length):
    out = bytearray()
    while len(out) < length:
        tag = _choose(r, [b"HDR", b"BIN", b"DAT", b"IMG", b"AUD"])  # 3 bytes
        out.extend(tag)
        remaining = max(0, length - len(out) - 6)
        seglen = 0 if remaining <= 0 else _rand(r, 0, min(64, remaining))
        out.extend(struct.pack('<H', seglen))
        mode = _rand(r, 0, 3)
        if mode == 0:
            seg = _gen_repeating(r, seglen)
        elif mode == 1:
            seg = _gen_random_low_entropy(r, seglen)
        elif mode == 2:
            seg = _gen_incrementing(r, seglen)
        else:
            seg = _gen_random_high_entropy(r, seglen)
        out.extend(seg)
        out.extend(b"\x00\xFF")
    return bytes(out[:length])


def _gen_palindromic(r, length):
    half = (length + 1) // 2
    left = bytes(r.getrandbits(8) for _ in range(half))
    pal = left + left[::-1]
    return pal[:length]


def _mix_chunks(r, target_len):
    gens = [
        _gen_repeating,
        _gen_incrementing,
        _gen_random_low_entropy,
        _gen_random_high_entropy,
        _gen_text_english,
        _gen_binary_patterns,
        _gen_palindromic,
    ]
    out = bytearray()
    while len(out) < target_len:
        remaining = target_len - len(out)
        # choose a base chunk size
        if remaining > 128 and r.random() < 0.5:
            chunk_len = _rand(r, 33, min(256, remaining))
        else:
            chunk_len = _rand(r, 1, min(64, remaining))
        gen = _choose(r, gens)
        # Ensure text chunks have enough room for words
        if gen is _gen_text_english and chunk_len < 8:
            chunk_len = min(remaining, max(8, chunk_len))
        # For repeating runs, sometimes choose a longer run but guard bounds
        if gen is _gen_repeating and r.random() < 0.3 and remaining > 0:
            upper = min(512, remaining)
            lower = min(64, upper)
            if upper >= lower:
                long_len = _rand(r, lower, upper)
                chunk_len = min(remaining, max(chunk_len, long_len))
        out.extend(gen(r, chunk_len))
        if r.random() < 0.2 and len(out) < target_len:
            sep_len = _rand(r, 1, min(8, target_len - len(out)))
            out.extend(bytes([0]) * sep_len)
    return bytes(out[:target_len])


def _size_profile(r):
    profiles = [
        0,
        _rand(r, 1, 3),
        _rand(r, 4, 15),
        _rand(r, 16, 127),
        _rand(r, 128, 255),
        _rand(r, 256, 511),
        _rand(r, 512, 900),
        _rand(r, 900, _TARGET_MAX),
        _TARGET_MAX,
    ]
    return _choose(r, profiles)


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    total_len = _size_profile(r)
    total_len = max(0, min(total_len, min(_TARGET_MAX, _MAX_TOTAL)))

    if total_len == 0:
        return b""

    strategy = _choose(r, [
        'repeat', 'increment', 'low_entropy', 'high_entropy',
        'text', 'binary', 'pal', 'mix'
    ])

    if strategy == 'repeat':
        data = _gen_repeating(r, total_len)
    elif strategy == 'increment':
        data = _gen_incrementing(r, total_len)
    elif strategy == 'low_entropy':
        data = _gen_random_low_entropy(r, total_len)
    elif strategy == 'high_entropy':
        data = _gen_random_high_entropy(r, total_len)
    elif strategy == 'text':
        data = _gen_text_english(r, total_len)
    elif strategy == 'binary':
        data = _gen_binary_patterns(r, total_len)
    elif strategy == 'pal':
        data = _gen_palindromic(r, total_len)
    else:
        data = _mix_chunks(r, total_len)

    # Optional small prefix to vary early bytes; ensure size cap
    if len(data) > 0 and r.random() < 0.35:
        prefixes = [
            b"\x00" * _rand(r, 1, 16),
            b"HTTP/1.1 ",
            b"{\"key\":\"value\"}",
            b"PK\x03\x04",
            b"ID3",
            b"\x89PNG\r\n\x1a\n",
        ]
        prefix_choice = _choose(r, prefixes)
        max_pre = max(0, _TARGET_MAX - len(data))
        prefix = prefix_choice[:max_pre]
        data = (prefix + data)[:_TARGET_MAX]

    return data
